import sys
sys.path.insert(0, 'src')
from marshmallow import Schema, fields, validates_schema, ValidationError

# Test m2: dict-style ValidationError remapping
class DictStyleSchema(Schema):
    ip_addresses = fields.String(data_key='ipAddresses')

    @validates_schema
    def validate_ip(self, data, **kwargs):
        raise ValidationError({'ip_addresses': 'err'})

try:
    result = DictStyleSchema().load({'ipAddresses': 'x'})
    print(f"ERROR: Should have raised ValidationError")
except ValidationError as e:
    print(f"ValidationError messages: {e.messages}")
    assert 'ipAddresses' in e.messages, f"Expected 'ipAddresses' key, got keys: {list(e.messages.keys())}"
    print("m2 dict-style test passed!")
